import sys
sys.path.insert(0, '/tmp/venv/lib/python3.12/site-packages')
from rdflib import Graph

g = Graph()
g.parse('/app/university_graph.ttl', format='turtle')

q = """
PREFIX uni: <http://university.org/ontology/>
SELECT ?name ?role ?dept ?uni ?country WHERE {
  ?p a uni:Person ;
     uni:hasName ?name ;
     uni:role ?role ;
     uni:worksIn ?dept .
  ?dept uni:belongsTo ?uni .
  ?uni uni:locatedInCountry ?country .
  FILTER (CONTAINS(?role, "Professor"))
}
ORDER BY ?name
"""
print('All professors with departments:')
for row in g.query(q):
    print(row)

# Now filter full professors (exclude Assistant)
q2 = """
PREFIX uni: <http://university.org/ontology/>
SELECT DISTINCT ?name ?role WHERE {
  ?p a uni:Person ;
     uni:hasName ?name ;
     uni:role ?role .
  FILTER (CONTAINS(?role, "Professor") && !CONTAINS(?role, "Assistant"))
}
"""
print('\nFull professors:')
for row in g.query(q2):
    print(row)

# Which full professors work in departments with >10 students and EU?
q3 = """
PREFIX uni: <http://university.org/ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT DISTINCT ?name ?dept ?country WHERE {
  ?p a uni:Person ;
     uni:hasName ?name ;
     uni:role ?role ;
     uni:worksIn ?dept .
  FILTER (CONTAINS(?role, "Professor") && !CONTAINS(?role, "Assistant"))
  ?dept uni:belongsTo ?uni .
  ?uni uni:locatedInCountry ?country .
  FILTER (?country IN ("DE", "ES", "FR", "GR", "PT"))
  # Department with >10 students
  {
    SELECT ?dept2 (COUNT(DISTINCT ?student) AS ?cnt) WHERE {
      ?class uni:isTaughtIn ?dept2 .
      ?student uni:isEnrolledIn ?class .
      ?student uni:hasEnrollmentDate ?enrollDate .
      OPTIONAL { ?student uni:hasGraduationDate ?gradDate }
      FILTER (?enrollDate <= "2025-08-16"^^xsd:date)
      FILTER (!BOUND(?gradDate) || ?gradDate > "2025-08-16"^^xsd:date)
    }
    GROUP BY ?dept2
    HAVING (?cnt > 10)
  }
  FILTER (?dept = ?dept2)
}
"""
print('\nFull professors meeting all criteria:')
for row in g.query(q3):
    print(row)
EOF

