cat > /app/solution.sparql << 'EOF'
PREFIX uni: <http://university.org/ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?professorName (GROUP_CONCAT(DISTINCT ?country; separator=", ") AS ?countries)
WHERE {
  ?professor a uni:Person ;
             uni:hasName ?professorName ;
             uni:role ?role .
  FILTER (CONTAINS(?role, "Professor") && !CONTAINS(?role, "Assistant"))

  ?professor uni:worksIn ?department .
  ?department uni:belongsTo ?university .
  ?university uni:locatedInCountry ?country .
  FILTER (?country IN ("DE", "ES", "FR", "GR", "PT"))

  # At least one department they work in has >10 currently enrolled students in classes taught in that department
  ?professor uni:worksIn ?dept .
  {
    SELECT ?dept (COUNT(DISTINCT ?student) AS ?cnt) WHERE {
      ?class uni:isTaughtIn ?dept .
      ?student uni:isEnrolledIn ?class .
      ?student uni:hasEnrollmentDate ?enrollDate .
      OPTIONAL { ?student uni:hasGraduationDate ?gradDate }
      FILTER (?enrollDate <= "2025-08-16"^^xsd:date)
      FILTER (!BOUND(?gradDate) || ?gradDate > "2025-08-16"^^xsd:date)
    }
    GROUP BY ?dept
  }
  FILTER (?cnt > 10)
}
GROUP BY ?professor ?professorName
EOF
